import{_ as t,o as e,c as r,a4 as s}from"./chunks/framework.BUqnS5H7.js";const m=JSON.parse('{"title":"Quorum 与 Raft","description":"","frontmatter":{},"headers":[],"relativePath":"rabbitmq/07-clustering/chapter-03-quorum-raft.md","filePath":"rabbitmq/07-clustering/chapter-03-quorum-raft.md"}'),l={name:"rabbitmq/07-clustering/chapter-03-quorum-raft.md"};function n(i,a,d,c,u,o){return e(),r("div",null,[...a[0]||(a[0]=[s(`<h1 id="quorum-与-raft" tabindex="-1" data-src-line="1" data-src-file="rabbitmq/07-clustering/chapter-03-quorum-raft.md">Quorum 与 Raft <a class="header-anchor" href="#quorum-与-raft" aria-label="Permalink to &quot;Quorum 与 Raft&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="rabbitmq/07-clustering/chapter-03-quorum-raft.md"><p data-src-line="3" data-src-file="rabbitmq/07-clustering/chapter-03-quorum-raft.md">Quorum Queue 基于 Raft 共识协议实现高可用。理解 Raft 是理解 Quorum Queue 行为的关键。</p></blockquote><h2 id="_1-raft-协议核心" tabindex="-1" data-src-line="5" data-src-file="rabbitmq/07-clustering/chapter-03-quorum-raft.md">1. Raft 协议核心 <a class="header-anchor" href="#_1-raft-协议核心" aria-label="Permalink to &quot;1. Raft 协议核心&quot;">​</a></h2><p data-src-line="7" data-src-file="rabbitmq/07-clustering/chapter-03-quorum-raft.md">Raft 是一种分布式共识算法，保证多个节点对日志顺序达成一致。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Leader ──日志复制──▶ Follower 1</span></span>
<span class="line"><span>                  ──▶ Follower 2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>写入成功条件：Leader + 多数 Follower 确认</span></span>
<span class="line"><span>  3 节点：需要 2 个确认（Leader + 1 Follower）</span></span>
<span class="line"><span>  5 节点：需要 3 个确认（Leader + 2 Follower）</span></span></code></pre></div><h2 id="_2-quorum-queue-中的-raft" tabindex="-1" data-src-line="18" data-src-file="rabbitmq/07-clustering/chapter-03-quorum-raft.md">2. Quorum Queue 中的 Raft <a class="header-anchor" href="#_2-quorum-queue-中的-raft" aria-label="Permalink to &quot;2. Quorum Queue 中的 Raft&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Producer ──▶ Leader Node ──Raft 日志──▶ Follower 1</span></span>
<span class="line"><span>                                   ──▶ Follower 2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Consumer ◀── Leader Node（只从 Leader 读取）</span></span></code></pre></div><ul data-src-line="27" data-src-file="rabbitmq/07-clustering/chapter-03-quorum-raft.md"><li data-src-line="27" data-src-file="rabbitmq/07-clustering/chapter-03-quorum-raft.md"><strong>写入</strong>：消息先写入 Leader 的 Raft 日志，复制到多数节点后返回 Confirm</li><li data-src-line="28" data-src-file="rabbitmq/07-clustering/chapter-03-quorum-raft.md"><strong>读取</strong>：只从 Leader 读取（Quorum Queue 不支持从 Follower 读）</li><li data-src-line="29" data-src-file="rabbitmq/07-clustering/chapter-03-quorum-raft.md"><strong>Leader 选举</strong>：Leader 崩溃后，Follower 自动发起选举</li></ul><h2 id="_3-leader-选举" tabindex="-1" data-src-line="31" data-src-file="rabbitmq/07-clustering/chapter-03-quorum-raft.md">3. Leader 选举 <a class="header-anchor" href="#_3-leader-选举" aria-label="Permalink to &quot;3. Leader 选举&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Leader 崩溃</span></span>
<span class="line"><span>  → Follower 发现心跳超时</span></span>
<span class="line"><span>  → Follower 转为 Candidate，发起投票</span></span>
<span class="line"><span>  → 多数节点投票 → 新 Leader 当选</span></span>
<span class="line"><span>  → 耗时通常 1-5 秒</span></span></code></pre></div><h2 id="_4-日志复制与持久性" tabindex="-1" data-src-line="41" data-src-file="rabbitmq/07-clustering/chapter-03-quorum-raft.md">4. 日志复制与持久性 <a class="header-anchor" href="#_4-日志复制与持久性" aria-label="Permalink to &quot;4. 日志复制与持久性&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>消息写入流程：</span></span>
<span class="line"><span>  1. Producer 发送消息到 Leader</span></span>
<span class="line"><span>  2. Leader 追加到 Raft 日志（磁盘）</span></span>
<span class="line"><span>  3. Leader 复制日志到 Followers</span></span>
<span class="line"><span>  4. 多数节点写入磁盘后 → 返回 Producer Confirm</span></span>
<span class="line"><span>  5. Leader 提交（commit）→ 消息可被消费</span></span></code></pre></div><p data-src-line="52" data-src-file="rabbitmq/07-clustering/chapter-03-quorum-raft.md"><strong>持久性保证</strong>：只要多数节点不同时崩溃，消息就不会丢。</p><h2 id="_5-quorum-queue-的脑裂处理" tabindex="-1" data-src-line="54" data-src-file="rabbitmq/07-clustering/chapter-03-quorum-raft.md">5. Quorum Queue 的脑裂处理 <a class="header-anchor" href="#_5-quorum-queue-的脑裂处理" aria-label="Permalink to &quot;5. Quorum Queue 的脑裂处理&quot;">​</a></h2><p data-src-line="56" data-src-file="rabbitmq/07-clustering/chapter-03-quorum-raft.md">Raft 协议天然防止脑裂：</p><ul data-src-line="58" data-src-file="rabbitmq/07-clustering/chapter-03-quorum-raft.md"><li data-src-line="58" data-src-file="rabbitmq/07-clustering/chapter-03-quorum-raft.md">网络分区时，少数派分区的节点无法获得多数投票，不能选出 Leader</li><li data-src-line="59" data-src-file="rabbitmq/07-clustering/chapter-03-quorum-raft.md">多数派分区正常工作</li><li data-src-line="60" data-src-file="rabbitmq/07-clustering/chapter-03-quorum-raft.md">网络恢复后，少数派同步多数派的数据</li></ul><h2 id="_6-性能特征" tabindex="-1" data-src-line="62" data-src-file="rabbitmq/07-clustering/chapter-03-quorum-raft.md">6. 性能特征 <a class="header-anchor" href="#_6-性能特征" aria-label="Permalink to &quot;6. 性能特征&quot;">​</a></h2><table tabindex="0"><thead data-src-line="64" data-src-file="rabbitmq/07-clustering/chapter-03-quorum-raft.md"><tr data-src-line="64" data-src-file="rabbitmq/07-clustering/chapter-03-quorum-raft.md"><th style="text-align:left;">维度</th><th style="text-align:left;">特征</th></tr></thead><tbody data-src-line="66" data-src-file="rabbitmq/07-clustering/chapter-03-quorum-raft.md"><tr data-src-line="66" data-src-file="rabbitmq/07-clustering/chapter-03-quorum-raft.md"><td style="text-align:left;">写入延迟</td><td style="text-align:left;">1-5ms（需要 Raft 共识）</td></tr><tr data-src-line="67" data-src-file="rabbitmq/07-clustering/chapter-03-quorum-raft.md"><td style="text-align:left;">读取延迟</td><td style="text-align:left;">微秒级（直接从 Leader 读）</td></tr><tr data-src-line="68" data-src-file="rabbitmq/07-clustering/chapter-03-quorum-raft.md"><td style="text-align:left;">吞吐量</td><td style="text-align:left;">2-5 万 msg/s（3 节点）</td></tr><tr data-src-line="69" data-src-file="rabbitmq/07-clustering/chapter-03-quorum-raft.md"><td style="text-align:left;">故障恢复</td><td style="text-align:left;">1-5 秒（Leader 重选）</td></tr></tbody></table><h2 id="_7-集群大小建议" tabindex="-1" data-src-line="71" data-src-file="rabbitmq/07-clustering/chapter-03-quorum-raft.md">7. 集群大小建议 <a class="header-anchor" href="#_7-集群大小建议" aria-label="Permalink to &quot;7. 集群大小建议&quot;">​</a></h2><table tabindex="0"><thead data-src-line="73" data-src-file="rabbitmq/07-clustering/chapter-03-quorum-raft.md"><tr data-src-line="73" data-src-file="rabbitmq/07-clustering/chapter-03-quorum-raft.md"><th style="text-align:left;">节点数</th><th style="text-align:left;">容错</th><th style="text-align:left;">适用场景</th></tr></thead><tbody data-src-line="75" data-src-file="rabbitmq/07-clustering/chapter-03-quorum-raft.md"><tr data-src-line="75" data-src-file="rabbitmq/07-clustering/chapter-03-quorum-raft.md"><td style="text-align:left;">3</td><td style="text-align:left;">容忍 1 节点故障</td><td style="text-align:left;">大多数场景</td></tr><tr data-src-line="76" data-src-file="rabbitmq/07-clustering/chapter-03-quorum-raft.md"><td style="text-align:left;">5</td><td style="text-align:left;">容忍 2 节点故障</td><td style="text-align:left;">高可靠性要求</td></tr><tr data-src-line="77" data-src-file="rabbitmq/07-clustering/chapter-03-quorum-raft.md"><td style="text-align:left;">7</td><td style="text-align:left;">容忍 3 节点故障</td><td style="text-align:left;">极高可靠性（少用）</td></tr></tbody></table><p data-src-line="79" data-src-file="rabbitmq/07-clustering/chapter-03-quorum-raft.md"><strong>不要用偶数节点</strong>：4 节点和 3 节点的容错能力相同（都只能容忍 1 个故障），但多了一个节点的开销。</p>`,21)])])}const f=t(l,[["render",n]]);export{m as __pageData,f as default};
